"""Oracle DB-API connection and schema bootstrap; uses bound named parameters."""
from __future__ import annotations
import os
from contextlib import contextmanager
from typing import Iterator
try:
    import oracledb
except ImportError:  # permits dependency-free unit tests
    oracledb = None

SCHEMA = (
 "CREATE TABLE eventforge_users (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR2(320) UNIQUE NOT NULL, password_hash VARCHAR2(512) NOT NULL, display_name VARCHAR2(120) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL)",
 "CREATE TABLE eventforge_events (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id NUMBER NOT NULL, name VARCHAR2(200) NOT NULL, event_datetime TIMESTAMP WITH TIME ZONE NOT NULL, venue VARCHAR2(300), capacity NUMBER, budget_limit NUMBER(18,2), status VARCHAR2(30) NOT NULL, description CLOB, confirmed_guest_count NUMBER DEFAULT 0 NOT NULL)",
)
class OracleDatabase:
    def __init__(self, dsn: str, user: str, password: str) -> None: self._dsn,self._user,self._password=dsn,user,password
    @contextmanager
    def transaction(self) -> Iterator[object]:
        if oracledb is None: raise RuntimeError("python-oracledb is not installed")
        connection=oracledb.connect(user=self._user,password=self._password,dsn=self._dsn)
        try:
            yield connection; connection.commit()
        except BaseException:
            connection.rollback(); raise
        finally: connection.close()
    def bootstrap(self) -> None:
        with self.transaction() as connection:
            with connection.cursor() as cursor:
                for statement in SCHEMA:
                    try: cursor.execute(statement)
                    except oracledb.DatabaseError as exc:
                        if getattr(exc.args[0],"code",None) != 955: raise

def database_from_environment() -> OracleDatabase:
    return OracleDatabase(os.getenv("ORACLE_DSN","localhost:1521/FREEPDB1"),os.getenv("ORACLE_USER","eventforge"),os.getenv("ORACLE_PASSWORD",""))
